    cin &gt;&gt; n;
    vector&lt;int&gt; d;  // d[k] — наименьший конец возрастающей подпоследовательности длины k + 1
    for (int i = 0; i &lt; n; i++) {
        int x;
        cin &gt;&gt; x;
        auto it = lower_bound(d.begin(), d.end(), x);  // первый элемент &gt;= x
        if (it == d.end()) d.push_back(x);  // x продлевает самую длинную
        else *it = x;                       // x — новый, меньший конец для этой длины
    }
    cout &lt;&lt; d.size() &lt;&lt; "\n";
}
