int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q;
    cin &gt;&gt; n &gt;&gt; m &gt;&gt; q;
    // S[i][j] — сумма от (1, 1) до (i, j); S[0][j] = S[i][0] = 0
    vector&lt;vector&lt;long long&gt;&gt; S(n + 1, vector&lt;long long&gt;(m + 1, 0));
    for (int i = 1; i &lt;= n; i++)
        for (int j = 1; j &lt;= m; j++) {
            long long x;
            cin &gt;&gt; x;
            S[i][j] = x + S[i - 1][j] + S[i][j - 1] - S[i - 1][j - 1];
        }
    while (q--) {
        int x1, y1, x2, y2;
        cin &gt;&gt; x1 &gt;&gt; y1 &gt;&gt; x2 &gt;&gt; y2;
        cout &lt;&lt; S[x2][y2] - S[x1 - 1][y2] - S[x2][y1 - 1]
                + S[x1 - 1][y1 - 1] &lt;&lt; "\n";
    }
}
